new = "function commandCenter(){const s=<?=$commandCenterJson?>,perm=<?=$permissionsJson?>;const f=n=>n.toLocaleString();const button=(key,label,cls='')=>perm[key]?'<button class=\"button '+cls+' cc-server-action\" data-action=\"'+key+'\">'+label+'</button>':'<button class=\"button\" disabled>'+label+' (restricted)</button>';const resources=Object.entries(s.resources).map(([k,v])=>'<div class=\"cc-resource\"><small>'+k+'</small><strong>'+f(v)+'</strong><div class=\"cc-bar\"><i style=\"width:'+Math.min(100,Math.max(8,Math.round(v/12400)))+'%\"></i></div></div>').join('');const queues=s.queues.map(q=>'<div class=\"cc-row\"><div><strong>'+q.name+'</strong><small>'+q.type+' queue · database-backed completion</small></div><span class=\"cc-badge\">'+q.remaining+'</span></div>').join('');const missions=s.missions.map(m=>'<div class=\"cc-mission\"><strong>'+m.type+'</strong><span>'+m.target+'</span><span class=\"cc-badge\">'+m.eta+'</span></div>').join('');const events=s.events.map(e=>'<div class=\"cc-event\">'+e+'</div>').join('');$('section').textContent='COMMAND CENTER';$('title').textContent='Command Center';$('description').textContent='Server-authoritative realm operations, colony life support, fleet movement, and turn settlement in one OGame-inspired command view.';$('content').innerHTML='<div class=\"cc-resource-strip\">'+resources+'</div><div class=\"cc-grid\"><div class=\"cc-card cc-wide\"><div class=\"eyebrow\">COLONY OVERVIEW</div><h2>'+s.colony.name+'</h2><div class=\"grid\"><div class=\"metric\"><span>Population</span><strong>'+f(s.colony.population)+'</strong><small>Morale '+Math.round(s.colony.morale*100)+'%</small></div><div class=\"metric\"><span>Life support</span><strong>'+f(s.resources.food)+' / '+f(s.resources.water)+'</strong><small>Food / Water stock</small></div><div class=\"metric\"><span>Production</span><strong>'+f(s.colony.food_per_hour)+' / '+f(s.colony.water_per_hour)+'</strong><small>Hourly consumption</small></div></div><div class=\"cc-feedback\">Systems nominal · state loaded from players, player_resources, player_planets, rankings, and game_events</div></div><div class=\"cc-card cc-side\"><div class=\"eyebrow\">SERVER ACTIONS</div><h2>Buttons & forms</h2><div class=\"cc-actions\">'+button('process_turns','Process turns','dark')+button('choose_target','Choose target')+button('review_reports','Review reports')+'</div><div class=\"cc-permission\">Permission checks: authenticated commander · CSRF required · action validated in actions/game.php</div><div id=\"feedback\" class=\"cc-feedback\" style=\"display:none\"></div></div><div class=\"cc-card cc-wide\"><div class=\"eyebrow\">ACTIVE QUEUES</div><h2>Construction & research</h2>'+queues+'</div><div class=\"cc-card cc-side\"><div class=\"eyebrow\">FLEET MOVEMENTS</div><h2>Mission control</h2>'+missions+'</div><div class=\"cc-card cc-wide\"><div class=\"eyebrow\">COMMAND LOG</div><h2>Recent events</h2>'+events+'</div><div class=\"cc-card cc-side\"><div class=\"eyebrow\">PAGE CONTRACT</div><h2>Dashboard / Command Center</h2><p class=\"cc-note\">The browser submits only player intent. PHP services own the transaction, permission check, resource settlement, and result message.</p><div class=\"pill\">process_turns</div><div class=\"pill\">players</div><div class=\"pill\">player_resources</div><div class=\"pill\">rankings</div><div class=\"pill\">game_events</div></div></div>';document.querySelectorAll('.cc-server-action').forEach(b=>b.onclick=()=>{const f=$('feedback');f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → POST actions/game.php → permission check → transaction → refreshed database state.'});document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.page===selected))}function render(){const p=all.find(x=>x.key===selected)||all[0];selected=p.key;if(selected==='dashboard'){commandCenter();return}$('section').textContent=(p.group||'SYSTEM').toUpperCase();$('title').textContent=p.title;$('description').textContent='Interactive PHP page preview for '+p.title+'. Review the intended layout, controls, server action intent, data reads, and result state.';$('content').innerHTML='<div class=\"grid\"><div class=\"card\"><div class=\"eyebrow\">PAGE CONTROLS</div><h2>Forms & buttons</h2>'+((p.controls||[]).map(x=>'<div class=\"status\">'+x+'</div>').join('')||'<div class=\"wire\">Read-only information view</div>')+'</div><div class=\"card\"><div class=\"eyebrow\">BACKEND</div><h2>PHP actions</h2>'+((p.actions||[]).map(x=>'<span class=\"pill\">'+x+'</span>').join('')||'<div class=\"wire\">No state-changing action</div>')+'</div><div class=\"card\"><div class=\"eyebrow\">SQL DATA</div><h2>Tables used</h2>'+((p.tables||[]).map(x=>'<span class=\"pill\">'+x+'</span>').join('')||'<div class=\"wire\">No table mapping</div>')+'</div><div class=\"card wide\"><div class=\"eyebrow\">PAGE DESIGN</div><h2>'+p.title+' content area</h2><div class=\"wire\">This PHP preview represents the page shell, nested navigation, accessible controls, server-side action mapping, database dependencies, validation feedback, loading state, empty state, success result, and error result for <b>'+p.title+'</b>.</div></div><div class=\"card\"><div class=\"eyebrow\">ROUTE</div><h2>PHP entrypoint</h2><div class=\"metric\"><strong>/pages/'+p.key+'.php</strong><small>Shared authenticated front controller</small></div></div></div>';document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.page===selected))}"
